     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '交子之环',
    '交子之环，位于四川省成都市交子大道177号中海国际中心。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(104.059498, 30.581982), 4326)::geography,
    1,
    4.20,
    0,
    '交子大道177号中海国际中心',
    '成都市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['风景名胜', '成都市', '四川省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '交子之环'
      AND COALESCE(address, '') = '交子大道177号中海国际中心'
      AND COALESCE(city, '') = '成都市'
);

