     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '大同市御河生态园',
    '大同市御河生态园，位于山西省大同市滨河路与御河南路交叉口南240米。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(113.324499, 40.087957), 4326)::geography,
    1,
    4.20,
    0,
    '滨河路与御河南路交叉口南240米',
    '大同市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['公园', '大同市', '山西省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '大同市御河生态园'
      AND COALESCE(address, '') = '滨河路与御河南路交叉口南240米'
      AND COALESCE(city, '') = '大同市'
);

