     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '沈水湾公园',
    '沈水湾公园，位于辽宁省沈阳市沈水路589号。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(123.419541, 41.751388), 4326)::geography,
    1,
    4.20,
    0,
    '沈水路589号',
    '沈阳市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['公园', '沈阳市', '辽宁省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '沈水湾公园'
      AND COALESCE(address, '') = '沈水路589号'
      AND COALESCE(city, '') = '沈阳市'
);

