     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '哈尔滨市长青公园',
    '哈尔滨市长青公园，位于黑龙江省哈尔滨市南极街116号。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(126.640335, 45.769836), 4326)::geography,
    1,
    4.20,
    0,
    '南极街116号',
    '哈尔滨市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['公园广场', '哈尔滨市', '黑龙江省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '哈尔滨市长青公园'
      AND COALESCE(address, '') = '南极街116号'
      AND COALESCE(city, '') = '哈尔滨市'
);

