     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '丁香园',
    '丁香园，位于青海省西宁市南山路。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(101.769922, 36.615128), 4326)::geography,
    1,
    4.20,
    0,
    '南山路',
    '西宁市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['旅游景点', '西宁市', '青海省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '丁香园'
      AND COALESCE(address, '') = '南山路'
      AND COALESCE(city, '') = '西宁市'
);

