     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '下密寺',
    '下密寺，位于西藏自治区拉萨市北京东路。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(91.135745, 29.653345), 4326)::geography,
    1,
    4.20,
    0,
    '北京东路',
    '拉萨市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['寺庙道观', '拉萨市', '西藏自治区'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '下密寺'
      AND COALESCE(address, '') = '北京东路'
      AND COALESCE(city, '') = '拉萨市'
);

