     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '鹿冲关森林公园',
    '鹿冲关森林公园，位于贵州省贵阳市盐沙大道附近。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(106.707259, 26.626134), 4326)::geography,
    1,
    4.20,
    0,
    '盐沙大道附近',
    '贵阳市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['风景名胜', '贵阳市', '贵州省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '鹿冲关森林公园'
      AND COALESCE(address, '') = '盐沙大道附近'
      AND COALESCE(city, '') = '贵阳市'
);

