     opening_hours, ticket_price, duration_minutes, crowd_level, images, thumbnail_url, tags, status)
SELECT
    '洪石公园',
    '洪石公园，位于安徽省合肥市石台路与孔塘支路交叉口东南140米。数据来源：高德地图开放平台 POI。',
    ST_SetSRID(ST_MakePoint(117.238315, 31.828850), 4326)::geography,
    1,
    4.20,
    0,
    '石台路与孔塘支路交叉口东南140米',
    '合肥市',
    '以景区公告为准',
    0,
    90,
    2,
    ARRAY[''],
    '',
    ARRAY['公园', '合肥市', '安徽省'],
    1
WHERE NOT EXISTS (
    SELECT 1 FROM scenic_spots
    WHERE name = '洪石公园'
      AND COALESCE(address, '') = '石台路与孔塘支路交叉口东南140米'
      AND COALESCE(city, '') = '合肥市'
);

